begin;
create function pg_temp.assert_ok(ok boolean, message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception '%', message; end if; end $$;
create function pg_temp.expect_error(statement text) returns void language plpgsql as $$ begin begin execute statement; exception when others then return; end; raise exception 'Expected rejection: %', statement; end $$;
insert into auth.users(id) values ('00000000-0000-4000-8000-000000000091'), ('00000000-0000-4000-8000-000000000092');
update public.profiles set active=true where id in ('00000000-0000-4000-8000-000000000091','00000000-0000-4000-8000-000000000092');
insert into public.events(id,tba_key,year,name,game_slug,created_by) values ('10000000-0000-4000-8000-000000000091','2026avatar',2026,'Avatar test','2026-rebuilt','00000000-0000-4000-8000-000000000091');
insert into public.teams(team_number,tba_team_key) values (91,'frc91');
insert into public.event_teams(event_id,team_number) values ('10000000-0000-4000-8000-000000000091',91);
insert into public.team_avatars(event_id,team_number,storage_path) values ('10000000-0000-4000-8000-000000000091',91,'10000000-0000-4000-8000-000000000091/91/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.webp');
insert into storage.objects(bucket_id,name) values ('team-avatars','10000000-0000-4000-8000-000000000091/91/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.webp');
select pg_temp.expect_error($s$insert into public.team_avatars(event_id,team_number,storage_path) values ('10000000-0000-4000-8000-000000000091',91,'bad.webp')$s$);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000092',true);
select pg_temp.assert_ok((select count(*)=1 from public.team_avatars),'Active scout reads event avatar metadata');
select pg_temp.assert_ok((select count(*)=1 from storage.objects where bucket_id='team-avatars'),'Active scout reads linked avatar object');
select pg_temp.expect_error($s$insert into storage.objects(bucket_id,name) values ('team-avatars','arbitrary.webp')$s$);
select pg_temp.expect_error($s$delete from public.team_avatars$s$);
reset role;
update public.profiles set active=false where id='00000000-0000-4000-8000-000000000092';
set local role authenticated;
select pg_temp.assert_ok((select count(*)=0 from public.team_avatars),'Inactive scout cannot read avatars');
select pg_temp.assert_ok((select count(*)=0 from storage.objects where bucket_id='team-avatars'),'Inactive scout cannot read avatar objects');
rollback;
